import React from 'react';
import './Services.css';

const Services = () => {
  const services = [
    {
      id: 1,
      title: "Color Consultation",
      description: "Expert advice on color schemes and combinations for your space",
      icon: "🎨",
      features: ["Free Consultation", "3D Visualization", "Custom Palettes"]
    },
    {
      id: 2,
      title: "Professional Application",
      description: "Skilled painters ensure perfect finish with our premium paints",
      icon: "👨🎨",
      features: ["Certified Painters", "Quality Guarantee", "Clean Workspace"]
    },
    {
      id: 3,
      title: "Surface Preparation",
      description: "Complete surface prep for optimal paint adhesion and longevity",
      icon: "🔧",
      features: ["Deep Cleaning", "Crack Filling", "Primer Application"]
    },
    {
      id: 4,
      title: "Maintenance Support",
      description: "Ongoing support and touch-up services to keep your paint fresh",
      icon: "🛠️",
      features: ["Annual Check-ups", "Touch-up Service", "Care Instructions"]
    }
  ];

  return (
    <section className="services section" id="services">
      <div className="container">
        <div className="section-header">
          <h2 className="section-title">Our Services</h2>
          <p className="section-subtitle">Complete painting solutions from consultation to maintenance</p>
        </div>

        <div className="services-container">
          {services.map((service) => (
            <div key={service.id} className="service-card">
              <div className="service-content">
                <div className="service-icon">{service.icon}</div>

                <h3 className="service-title">{service.title}</h3>
                <p className="service-description">{service.description}</p>

                <ul className="service-features">
                  {service.features.map((feature, idx) => (
                    <li key={idx}>✓ {feature}</li>
                  ))}
                </ul>
              </div>

              <div className="service-number">
                {String(service.id).padStart(2, '0')}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Services;
